const paths = {};
const add = (path, method, op) => {
  paths[path] ??= {};
  paths[path][method] = { responses: { ...common }, ...op, responses: { ...(op.responses ?? {}), ...common, ...(op.responses ?? {}) } };
  if (!paths[path][method].responses['200'] && !paths[path][method].responses['201'] && !paths[path][method].responses['204']) throw new Error(`no success response for ${method} ${path}`);
};
const T = { auth: 'Auth & profile', cat: 'Catalogue', veh: 'Vehicles', bk: 'Bookings', qt: 'Quotations', pay: 'Payments', loy: 'Loyalty', mem: 'Memberships', staff: 'Staff', inv: 'Inventory', adm: 'Admin', not: 'Notifications', pub: 'Public quote page', sys: 'System' };

add('/config', 'get', { tags: [T.sys], operationId: 'getConfig', summary: 'Public-safe feature flags (no auth)', security: [], responses: { 200: json(obj({ flags: obj({ cash_on_collection: bool(), payments_sandbox: bool(), whatsapp_enabled: bool() }) })) } });
add('/health', 'get', { tags: [T.sys], operationId: 'getHealth', summary: 'Liveness probe', security: [], responses: { 200: json(obj({ ok: bool(), version: str(), service: str(), time: dt() })) } });

// Auth
add('/auth/session', 'post', { tags: [T.auth], operationId: 'postAuthSession', summary: 'Upsert profile, claim seeded profile by e-mail, set custom claims', requestBody: body(obj({ app: enumOf(['customer', 'staff', 'admin']), full_name: str(), phone: str() }, ['app'])), responses: { 200: json(obj({ profile: ref('Profile'), outlet_ids: arr(uuid()), claims_updated: bool() })) } });
