add('/me', 'patch', { tags: [T.auth], operationId: 'patchMe', summary: 'Update editable profile fields', requestBody: body(obj({ full_name: str(), phone: nullable(str()), avatar_url: nullable(str()), marketing_opt_in: bool(), whatsapp_opt_in: bool(), push_opt_in: bool(), locale: str(), reduced_motion: bool(), haptics: bool() })), responses: { 200: json(obj({ profile: ref('Profile') })) } });
